<script lang="ts">
	import { onDestroy } from 'svelte';
	import Icon from './Icon.svelte';
	import { NOTE_COLORS, NOTE_NAMES, noteName } from '#lib/music/theory.ts';
	import { atlasChord, identifyTriad, nearestVoicing, pitchClass, tonnetz, transformTriad, voicePaths, type AtlasChord, type LatticeNode, type LatticeTriangle } from '#lib/harmony/atlas.ts';
	import type { PlotNote } from '#lib/types.ts';
	let { notes, title, root, stopToken, onplay, onstop }: {notes:readonly PlotNote[];title:string;root:number;stopToken:number;onplay:(notes:number[],label:string,sequence?:boolean)=>void;onstop:()=>void}=$props();
	let previous=$state<number[]>([]);
	let selectedStep=$state(0);
	let progression=$state<AtlasChord[]>([atlasChord(0),atlasChord(9,'minor'),atlasChord(5),atlasChord(7)]);
	let running=$state(false);
	let sequenceToken=$state(-1);
	const playing=$derived(running&&sequenceToken===stopToken);
	let currentStep=$state(-1);
	let tempo=$state(100);
	let showPaths=$state(true);
	let focused=$state('0:0');
	let keyboardFocus=$state(false);
	let latticeFocused=$state(false);
	let viewportWidth=$state<number|undefined>();
	const compact=$derived((viewportWidth??1200)<=700);
	let timer:ReturnType<typeof setTimeout>|undefined;
	const lattice=$derived(tonnetz(root));
	const midi=$derived(notes.map((note)=>note.midi));
	const chord=$derived(identifyTriad(midi));
	const paths=$derived(voicePaths(previous,midi));
	const previousChord=$derived(identifyTriad(previous));
	const shared=$derived(paths.filter((path)=>path.common).length);
	const activeTriangle=$derived(lattice.triangles.filter((triangle)=>triangle.chord.root===chord?.root&&triangle.chord.quality===chord?.quality).sort((a,b)=>Math.hypot(center(a).x-400,center(a).y-250)-Math.hypot(center(b).x-400,center(b).y-250))[0]);
	const chartCenter=$derived(latticeFocused&&keyboardFocus?(lattice.nodes.find((node)=>node.id===focused)??{x:400,y:250}):activeTriangle?center(activeTriangle):{x:400,y:250});
	function center(triangle:LatticeTriangle){return {x:triangle.nodes.reduce((sum,node)=>sum+node.x,0)/3,y:triangle.nodes.reduce((sum,node)=>sum+node.y,0)/3};}
	function points(triangle:LatticeTriangle){return triangle.nodes.map((node)=>`${node.x},${node.y}`).join(' ');}
	function audition(next:AtlasChord,sequence=false){previous=[...midi];const voicing=nearestVoicing(midi,next.notes);onplay(voicing,`${NOTE_NAMES[next.root]} ${next.quality}`,sequence);}
	function playNode(node:LatticeNode,event:MouseEvent){previous=[...midi];onplay([48+node.pitch],noteName(48+node.pitch));if(event.detail>0)(event.currentTarget as SVGElement).blur();}
	function playTriangle(triangle:LatticeTriangle,event:MouseEvent){audition(triangle.chord);if(event.detail>0)(event.currentTarget as SVGElement).blur();}
	function navigate(event:KeyboardEvent,node:LatticeNode){
		if(event.key==='Enter'||event.key===' '){event.preventDefault();if(!event.repeat){previous=[...midi];onplay([48+node.pitch],noteName(48+node.pitch));}return;}
		const shift=event.key==='ArrowRight'?[1,0]:event.key==='ArrowLeft'?[-1,0]:event.key==='ArrowUp'?[0,1]:event.key==='ArrowDown'?[0,-1]:null;
		if(!shift)return;event.preventDefault();keyboardFocus=true;
		const target=lattice.nodes.find((item)=>item.q===node.q+shift[0]&&item.r===node.r+shift[1]);if(target){focused=target.id;(event.currentTarget as SVGElement).ownerSVGElement?.querySelector<SVGElement>(`[data-node="${target.id}"]`)?.focus();}
	}
	function stopSequence(){clearTimeout(timer);running=false;currentStep=-1;}
	function playSequence(){stopSequence();sequenceToken=stopToken;running=true;let step=0;const token=stopToken;
		const next=()=>{if(token!==stopToken){stopSequence();return;}if(step>=progression.length){stopSequence();onstop();return;}currentStep=step;selectedStep=step;audition(progression[step],true);step++;timer=setTimeout(next,240000/tempo);};next();
	}
	function replaceStep(){if(chord)progression=progression.map((step,i)=>i===selectedStep?{...chord,notes:[...midi]}:step);}
	onDestroy(stopSequence);
</script>
<svelte:window bind:innerWidth={viewportWidth} onpointerdown={()=>keyboardFocus=false} onkeydown={(event)=>{if(event.key==='Tab')keyboardFocus=true;}} />
<div class="atlas-view">
	<div class="atlas-main">
		<div class="atlas-heading"><h1>{title}</h1><p>Follow the notes a chord leaves in place.</p></div>
		<svg class={['tonnetz',keyboardFocus&&'keyboard-focus']} viewBox={compact?`${chartCenter.x-225} ${chartCenter.y-175} 450 350`:'0 0 800 500'} onfocusin={()=>latticeFocused=true} onfocusout={(event)=>{if(!(event.relatedTarget instanceof Node)||!event.currentTarget.contains(event.relatedTarget))latticeFocused=false;}} role="group" aria-label="Playable Tonnetz. Horizontal neighbors are fifths; diagonal neighbors are thirds. Select a triangle to play a triad.">
			<defs><radialGradient id="atlas-fade"><stop offset="0" stop-color="white"/><stop offset=".75" stop-color="white"/><stop offset="1" stop-color="#666"/></radialGradient><mask id="atlas-mask"><rect width="800" height="500" fill="url(#atlas-fade)"/></mask><linearGradient id="active-triangle"><stop stop-color="#77dbea" stop-opacity=".15"/><stop offset="1" stop-color="#b3a2f4" stop-opacity=".12"/></linearGradient></defs>
			<g mask="url(#atlas-mask)">{#each lattice.triangles as triangle (triangle.id)}{@const selected=triangle.id===activeTriangle?.id}<polygon points={points(triangle)} class={['triad',selected&&'selected']} role="button" tabindex={selected?0:-1} aria-label={`Play ${NOTE_NAMES[triangle.chord.root]} ${triangle.chord.quality} triad`} aria-pressed={selected} onclick={(event)=>playTriangle(triangle,event)} onkeydown={(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();if(!event.repeat)audition(triangle.chord);}}} />{/each}</g>
			{#if activeTriangle}{#each activeTriangle.nodes as node,i (node.id)}{@const next=activeTriangle.nodes[(i+1)%3]}<line class="active-edge" x1={node.x} y1={node.y} x2={next.x} y2={next.y} stroke={NOTE_COLORS[i]} />{/each}{/if}
			{#each lattice.nodes as node (node.id)}{@const active=activeTriangle?.nodes.some((item)=>item.id===node.id)??false}{@const index=Math.max(0,notes.findIndex((note)=>pitchClass(note.midi)===node.pitch))}<g role="button" tabindex={node.id===focused?0:-1} data-node={node.id} aria-label={`Play ${NOTE_NAMES[node.pitch]}`} class={['node',active&&'active']} style:--note-color={NOTE_COLORS[index%3]} onclick={(event)=>playNode(node,event)} onkeydown={(event)=>navigate(event,node)}><circle cx={node.x} cy={node.y} r={compact?(active?27:25):(active?24:21)}/><text x={node.x} y={node.y+5} text-anchor="middle" aria-hidden="true">{NOTE_NAMES[node.pitch]}</text></g>{/each}
		</svg>
		<div class="lattice-caption"><span>Fifths across · Thirds diagonally</span><span>Click a note or a triangle</span></div>
		<div class="transforms" aria-label="Chord transformations"><span>Move one voice</span>{#each [{id:'parallel',name:'Parallel',hint:'Change the third'},{id:'relative',name:'Relative',hint:'Keep two common tones'},{id:'leading',name:'Leading-tone',hint:'Move by one semitone'}] as item (item.id)}<button type="button" disabled={!chord} title={item.hint} onclick={(event)=>{if(chord)audition(transformTriad(chord,item.id as 'parallel'|'relative'|'leading'));if(event.detail>0)event.currentTarget.blur();}}>{item.name}{#if chord}<small>{transformTriad(chord,item.id as 'parallel'|'relative'|'leading').label}</small>{/if}</button>{/each}</div>
		{#if !chord}<p class="triad-hint">Choose a major or minor triangle to explore its transformations.</p>{/if}
	</div>
	<aside class="atlas-inspector" aria-label="Chord relationships and progression">
		<h2>{previousChord&&chord?`${previousChord.label} → ${chord.label}`:'Between chords'}</h2>
		{#if previous.length===3&&midi.length===3}<p class="shared"><span class="shared-dots"><i></i><i></i></span>{shared} {shared===1?'shared note':'shared notes'}</p>{:else}<p class="intro">Choose a triangle. Move to its neighbors and hear the notes they share.</p>{/if}
		<div class="progression-heading"><h3>Progression</h3><span>4 steps</span></div>
		<div class="progression" aria-label="Four-step progression">{#each progression as step,i (i)}<button type="button" class={['progression-step',selectedStep===i&&'selected',playing&&currentStep===i&&'playing']} aria-label={`Progression step ${i+1}: ${step.label}`} aria-pressed={selectedStep===i} onclick={()=>{selectedStep=i;audition(step);}}><small>{i+1}</small>{step.label}</button>{/each}</div>
		<div class="progression-edit"><button type="button" disabled={!chord||playing} onclick={replaceStep}>Use current chord in step {selectedStep+1}</button></div>
		<div class="progression-transport"><button type="button" class="play-progression" aria-label={playing?'Stop progression':'Play progression'} onclick={()=>{if(playing){stopSequence();onstop();}else playSequence();}}><Icon name={playing?'stop':'play'} size={13}/>{playing?'Stop':'Play progression'}</button><label><input type="number" aria-label="Progression tempo" min="40" max="200" step="1" value={tempo} onchange={(event)=>tempo=Math.max(40,Math.min(200,Number(event.currentTarget.value)||100))}/><span>BPM</span></label></div>
		<p class="progression-note">Four beats per chord. Playing a key or choosing another chord stops the sequence.</p>
		<div class="paths-heading"><h3>Voice leading</h3><button type="button" aria-pressed={showPaths} onclick={()=>showPaths=!showPaths}>{showPaths?'Hide':'Show'} paths</button></div>
		{#if showPaths&&previous.length===3&&midi.length===3}<div class="voice-paths">{#each paths as path,i (i)}<div class="voice-path" style:--voice-color={NOTE_COLORS[i]}><span>{noteName(path.from)}</span><svg viewBox="0 0 100 32" aria-hidden="true"><line x1="5" y1="16" x2="95" y2={16-Math.max(-12,Math.min(12,path.semitones))} stroke="currentColor"/><circle cx="5" cy="16" r="2.5" fill="currentColor"/><circle cx="95" cy={16-Math.max(-12,Math.min(12,path.semitones))} r="2.5" fill="currentColor"/></svg><span>{noteName(path.to)}</span><small>{path.semitones>0?'+':''}{path.semitones}</small></div>{/each}</div><p class="path-note">Semitones, with octave placement shown.</p>{:else if showPaths}<p class="intro">Move between two triads to see each voice’s path.</p>{/if}
	</aside>
</div>
<style>
	.atlas-view{height:100%;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 258px;background:#000}.atlas-main{display:flex;flex-direction:column;min-height:450px;min-width:0;position:relative;overflow:hidden}.atlas-heading{position:absolute;left:27px;top:26px;z-index:2;pointer-events:none}.atlas-heading h1{font-size:29px;letter-spacing:-1px;font-weight:450;margin:0}.atlas-heading p{font-size:11px;color:#a3a3a3;margin:8px 0 0}.tonnetz{display:block;width:100%;height:100%;min-height:300px;flex:1;padding-top:65px}.triad{fill:transparent;stroke:#262626;stroke-width:1;cursor:pointer;outline:none}.triad:hover{fill:#ffffff0c;stroke:#777}.triad.selected{fill:url(#active-triangle);stroke:#9bbfc9}.triad:focus{outline:none}.keyboard-focus .triad:focus{stroke:#fff;stroke-width:2}.active-edge{stroke-width:2;pointer-events:none;filter:drop-shadow(0 0 4px #77dbea50)}.node{cursor:pointer;outline:none}.node circle{fill:#101010;stroke:#424242;stroke-width:1}.node text{fill:#c0c0c0;font-size:14px;font-weight:450;pointer-events:none;user-select:none}.node:hover circle{stroke:#ddd;fill:#252525}.node.active circle{stroke:var(--note-color);fill:color-mix(in srgb,var(--note-color) 14%,#111);filter:drop-shadow(0 0 7px color-mix(in srgb,var(--note-color) 45%,transparent));stroke-width:1.8}.node.active text{fill:#f4f4f4}.keyboard-focus .node:focus circle{stroke:#fff;stroke-width:3}.lattice-caption{display:flex;justify-content:space-between;padding:0 23px 15px;color:#777;font-size:10px;gap:10px}.transforms{display:flex;align-items:center;justify-content:center;gap:8px;padding:14px 19px;border-top:1px solid #2b2b2b;background:#0b0b0b}.transforms>span{color:#888;font-size:10px;margin-right:5px}.transforms button{border:1px solid #3a3a3a;background:#1d1d1d;color:#d8d8d8;border-radius:5px;font-size:11px;display:flex;gap:9px;align-items:center;padding:10px 12px;white-space:nowrap}.transforms button:hover:not(:disabled){background:#303030}.transforms button small{color:var(--cyan);font-size:11px}.triad-hint{margin:0;background:#0b0b0b;padding:0 20px 13px;color:#888;font-size:10px;text-align:center}.atlas-inspector{padding:27px 21px;min-height:0;overflow:auto;scrollbar-width:thin;background:#0b0b0b;border-left:1px solid #303030}.atlas-inspector h2{font-size:26px;letter-spacing:-.7px;font-weight:450;margin:0 0 16px}.shared{display:flex;align-items:center;gap:9px;font-size:12px;color:#c7c7c7;margin:0 0 28px}.shared-dots{display:flex}.shared-dots i{width:11px;height:11px;border-radius:50%;background:var(--cyan)}.shared-dots i+i{background:var(--iris);margin-left:-3px}.intro{color:#999;font-size:11px;line-height:1.7;margin:0 0 27px}.progression-heading,.paths-heading{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #303030;padding-top:23px;margin-bottom:16px}.progression-heading h3,.paths-heading h3{font-size:13px;font-weight:450;margin:0}.progression-heading>span{color:#777;font-size:10px}.progression{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}.progression-step{display:flex;flex-direction:column;align-items:center;gap:6px;min-height:59px;justify-content:center;border:1px solid #3d3d3d;background:#1a1a1a;color:#d5d5d5;font-size:15px;border-radius:5px}.progression-step small{font-size:9px;color:#777}.progression-step.selected{border-color:#777;background:#252525}.progression-step.playing{border-color:var(--cyan);color:var(--cyan);background:#142327}.progression-edit>button{background:none;border:0;padding:12px 0 15px;color:#a8a8a8;font-size:10px;text-decoration:underline;text-decoration-color:#555;text-underline-offset:3px}.progression-transport{display:flex;justify-content:space-between;gap:8px;align-items:center}.play-progression{display:flex;align-items:center;justify-content:center;gap:6px;background:#232323;border:1px solid #444;color:#ddd;border-radius:4px;padding:9px 10px;font-size:10px;white-space:nowrap}.progression-transport label{display:flex;align-items:center;gap:4px;color:#777;font-size:9px}.progression-transport input{width:40px;background:none;border:0;border-bottom:1px solid #454545;color:#ccc;font-size:11px;padding:5px 0;text-align:center;appearance:textfield}.progression-transport input::-webkit-inner-spin-button{appearance:none}.progression-note,.path-note{color:#777;font-size:10px;line-height:1.7;margin:14px 0 23px}.paths-heading button{font-size:10px;border:0;background:none;color:#a2a2a2;padding:4px 0}.voice-path{display:flex;align-items:center;gap:5px;color:var(--voice-color);font-size:11px}.voice-path svg{width:90px;flex:1;height:36px}.voice-path small{color:#999;width:18px;text-align:right;font-size:10px}.path-note{margin-top:11px}
	@media(max-width:1250px){.atlas-view{grid-template-columns:minmax(0,1fr) 225px}.atlas-inspector{padding:24px 17px}.transforms{gap:6px;padding:13px 10px}.transforms>span{display:none}.transforms button{padding:9px;font-size:10px;gap:6px}}
	@media(max-width:700px){.atlas-view{display:flex;flex-direction:column;height:auto}.atlas-main{min-height:450px;height:58vh;max-height:600px}.atlas-heading{left:20px;top:22px}.atlas-heading h1{font-size:26px}.tonnetz{padding-top:70px;min-height:300px}.node text{font-size:17px}.atlas-inspector{border-left:0;border-top:1px solid #303030;padding:23px 22px;overflow:visible}.lattice-caption{font-size:9px;padding:0 15px 13px}.transforms{padding:12px 10px}.transforms button{min-height:38px}.progression{gap:10px}.progression-step{min-height:65px}.voice-path svg{height:45px}.progression-transport input{width:55px;font-size:13px}.play-progression{font-size:11px;min-height:36px}.progression-note{max-width:270px}.progression-edit>button{min-height:42px}.triad-hint{font-size:9px}}
</style>
